  "depth" INTEGER NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, bundle) REFERENCES evidence_bundle (tenant, id),
  FOREIGN KEY (tenant, item) REFERENCES evidence_item (tenant, id),
  FOREIGN KEY (tenant, next) REFERENCES evidence_member (tenant, id)
);

CREATE TABLE evidence_seal (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "bundle" TEXT NOT NULL,
  "head" TEXT,
  "recorded_by" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, bundle) REFERENCES evidence_bundle (tenant, id),
  FOREIGN KEY (tenant, head) REFERENCES evidence_member (tenant, id)
);

CREATE TABLE evidence_source (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "key_" TEXT NOT NULL,
  "label" TEXT NOT NULL,
  PRIMARY KEY (tenant, id)
);

CREATE TABLE fulfillment (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "fulfillment_set" TEXT NOT NULL,
  "ordinal" INTEGER NOT NULL,
  "specification_pin" TEXT,
  "executor" TEXT NOT NULL,
  "requested_at" TEXT NOT NULL,
  "evidence" TEXT,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, fulfillment_set) REFERENCES fulfillment_set (tenant, id),
  FOREIGN KEY (tenant, specification_pin) REFERENCES specification_pin (tenant, id),
  FOREIGN KEY (tenant, executor) REFERENCES fulfillment_executor (tenant, id),
  FOREIGN KEY (tenant, evidence) REFERENCES evidence_seal (tenant, id)
);

CREATE TABLE fulfillment_end (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "fulfillment" TEXT NOT NULL,
  "start" TEXT,
  "outcome" TEXT NOT NULL,
  "coverage" TEXT NOT NULL,
  "ended_at" TEXT NOT NULL,
  "evidence" TEXT,
  "reason" TEXT NOT NULL,
  "recorded_by" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, fulfillment) REFERENCES fulfillment (tenant, id),
  FOREIGN KEY (tenant, start) REFERENCES fulfillment_start (tenant, id),
  FOREIGN KEY (tenant, evidence) REFERENCES evidence_seal (tenant, id)
);

CREATE TABLE fulfillment_executor (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "key_" TEXT NOT NULL,
  PRIMARY KEY (tenant, id)
);

CREATE TABLE fulfillment_replacement (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "prior" TEXT NOT NULL,
  "prior_end" TEXT NOT NULL,
  "replacement" TEXT NOT NULL,
  "reason" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, prior) REFERENCES fulfillment (tenant, id),
  FOREIGN KEY (tenant, prior_end) REFERENCES fulfillment_end (tenant, id),
  FOREIGN KEY (tenant, replacement) REFERENCES fulfillment (tenant, id)
);

CREATE TABLE fulfillment_set (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "label" TEXT NOT NULL,
  PRIMARY KEY (tenant, id)
);

CREATE TABLE fulfillment_start (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "fulfillment" TEXT NOT NULL,
  "began_at" TEXT NOT NULL,
  "recorded_by" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, fulfillment) REFERENCES fulfillment (tenant, id)
);

CREATE TABLE fulfillment_task_link (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "fulfillment" TEXT NOT NULL,
  "queue" TEXT NOT NULL,
  "task" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, fulfillment) REFERENCES fulfillment (tenant, id)
);

CREATE TABLE identifier (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "identifier_set" TEXT NOT NULL,
  "namespace" TEXT NOT NULL,
  "issuer" TEXT,
  "issuer_scope" TEXT NOT NULL,
  "value_" TEXT NOT NULL,
  "valid_from" TEXT NOT NULL,
  "valid_until" TEXT,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, identifier_set) REFERENCES identifier_set (tenant, id),
  FOREIGN KEY (tenant, issuer) REFERENCES issuer (tenant, id)
);

CREATE TABLE identifier_disposition (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "identifier" TEXT NOT NULL,
  "replacement" TEXT,
  "effective_at" TEXT NOT NULL,
  "reason" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, identifier) REFERENCES identifier (tenant, id),
  FOREIGN KEY (tenant, replacement) REFERENCES identifier (tenant, id)
);

CREATE TABLE identifier_set (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "label" TEXT NOT NULL,
  PRIMARY KEY (tenant, id)
);

CREATE TABLE issuer (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "key_" TEXT NOT NULL,
  PRIMARY KEY (tenant, id)
);

CREATE TABLE intake_form (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "definition" TEXT NOT NULL,
  "label" TEXT NOT NULL,
  "anonymous_allowed" INTEGER NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, definition) REFERENCES specification_pin (tenant, id)
);

CREATE TABLE submission (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "form" TEXT NOT NULL,
  "definition" TEXT NOT NULL,
  "submitter" TEXT,
  "source_key" TEXT NOT NULL,
  "submitted_at" TEXT NOT NULL,
  "raw" TEXT,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, form) REFERENCES intake_form (tenant, id),
  FOREIGN KEY (tenant, definition) REFERENCES specification_pin (tenant, id),
  FOREIGN KEY (tenant, submitter) REFERENCES party (tenant, id),
  FOREIGN KEY (tenant, raw) REFERENCES artifact_revision (tenant, id)
);

CREATE TABLE submission_validation (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "submission" TEXT NOT NULL,
  "run" TEXT NOT NULL,
  "finish" TEXT NOT NULL,
  "verdict" TEXT NOT NULL,
  "reason" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, submission) REFERENCES submission (tenant, id),
  FOREIGN KEY (tenant, run) REFERENCES evaluation_run (tenant, id),
  FOREIGN KEY (tenant, finish) REFERENCES evaluation_finish (tenant, id)
);

CREATE TABLE offboarding (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "activation" TEXT NOT NULL,
  "case_" TEXT NOT NULL,
  "policy" TEXT NOT NULL,
  "cleanup" TEXT NOT NULL,
  "transfer" TEXT NOT NULL,
  "obligation_review" TEXT NOT NULL,
  "approval" TEXT NOT NULL,
  "accepted" TEXT NOT NULL,
  "retention" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, activation) REFERENCES onboarding_activation (tenant, id),
  FOREIGN KEY (tenant, case_) REFERENCES case_ (tenant, id),
  FOREIGN KEY (tenant, policy) REFERENCES specification_pin (tenant, id),
  FOREIGN KEY (tenant, cleanup) REFERENCES fulfillment (tenant, id),
  FOREIGN KEY (tenant, transfer) REFERENCES fulfillment (tenant, id),
  FOREIGN KEY (tenant, obligation_review) REFERENCES evaluation_run (tenant, id),
  FOREIGN KEY (tenant, approval) REFERENCES decision_case (tenant, id),
  FOREIGN KEY (tenant, accepted) REFERENCES decision_option (tenant, id),
  FOREIGN KEY (tenant, retention) REFERENCES record (tenant, id)
);

CREATE TABLE offboarding_completion (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "offboarding" TEXT NOT NULL,
  "obligations" TEXT NOT NULL,
  "support" TEXT NOT NULL,
  "at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, offboarding) REFERENCES offboarding (tenant, id),
  FOREIGN KEY (tenant, obligations) REFERENCES evaluation_finish (tenant, id),
  FOREIGN KEY (tenant, support) REFERENCES evidence_seal (tenant, id)
);

CREATE TABLE onboarding (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "key_" TEXT NOT NULL,
  "case_" TEXT NOT NULL,
  "subject" TEXT NOT NULL,
  "party" TEXT,
  "principal" TEXT,
  "criteria" TEXT NOT NULL,
  "submission" TEXT NOT NULL,
  "validation" TEXT NOT NULL,
  "requirement" TEXT NOT NULL,
  "decision" TEXT NOT NULL,
  "accepted" TEXT NOT NULL,
  "gate_count" INTEGER NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, case_) REFERENCES case_ (tenant, id),
  FOREIGN KEY (tenant, subject) REFERENCES qualification_subject (tenant, id),
  FOREIGN KEY (tenant, party) REFERENCES party_subject (tenant, id),
  FOREIGN KEY (tenant, principal) REFERENCES delegation_subject (tenant, id),
  FOREIGN KEY (tenant, criteria) REFERENCES specification_pin (tenant, id),
  FOREIGN KEY (tenant, submission) REFERENCES submission (tenant, id),
  FOREIGN KEY (tenant, validation) REFERENCES submission_validation (tenant, id),
  FOREIGN KEY (tenant, requirement) REFERENCES qualification_requirement (tenant, id),
  FOREIGN KEY (tenant, decision) REFERENCES decision_case (tenant, id),
  FOREIGN KEY (tenant, accepted) REFERENCES decision_option (tenant, id)
);

