CREATE TABLE party_relationship (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "definition" TEXT NOT NULL,
  "from_party" TEXT NOT NULL,
  "to_party" TEXT NOT NULL,
  "scope" TEXT,
  "valid_from" TEXT NOT NULL,
  "valid_until" TEXT,
  "source" TEXT NOT NULL,
  "support" TEXT,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, definition) REFERENCES party_relationship_definition (tenant, id),
  FOREIGN KEY (tenant, from_party) REFERENCES party (tenant, id),
  FOREIGN KEY (tenant, to_party) REFERENCES party (tenant, id),
  FOREIGN KEY (tenant, scope) REFERENCES party_relationship_scope (tenant, id),
  FOREIGN KEY (tenant, support) REFERENCES evidence_seal (tenant, id)
);

CREATE TABLE party_relationship_definition (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "key_" TEXT NOT NULL,
  "pin" TEXT NOT NULL,
  "forward_label" TEXT NOT NULL,
  "inverse_label" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, pin) REFERENCES specification_pin (tenant, id)
);

CREATE TABLE party_relationship_end (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "relationship" TEXT NOT NULL,
  "replacement" TEXT,
  "effective_at" TEXT NOT NULL,
  "reason" TEXT NOT NULL,
  "recorded_by" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, relationship) REFERENCES party_relationship (tenant, id),
  FOREIGN KEY (tenant, replacement) REFERENCES party_relationship (tenant, id)
);

CREATE TABLE party_relationship_scope (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "label" TEXT NOT NULL,
  PRIMARY KEY (tenant, id)
);

CREATE TABLE party (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "label" TEXT NOT NULL,
  "identifiers" TEXT,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, identifiers) REFERENCES identifier_set (tenant, id)
);

CREATE TABLE principal_representation (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "party" TEXT NOT NULL,
  "principal" TEXT NOT NULL,
  "valid_from" TEXT NOT NULL,
  "valid_until" TEXT,
  "recorded_by" TEXT NOT NULL,
  "reason" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, party) REFERENCES party (tenant, id)
);

CREATE TABLE representation_revocation (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "representation" TEXT NOT NULL,
  "effective_at" TEXT NOT NULL,
  "recorded_by" TEXT NOT NULL,
  "reason" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, representation) REFERENCES principal_representation (tenant, id)
);

CREATE TABLE party_subject (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "subject" TEXT NOT NULL,
  "party" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, subject) REFERENCES qualification_subject (tenant, id),
  FOREIGN KEY (tenant, party) REFERENCES party (tenant, id)
);

CREATE TABLE qualification (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "subject" TEXT NOT NULL,
  "definition" TEXT NOT NULL,
  "level" TEXT,
  "issuer" TEXT NOT NULL,
  "issuer_record" TEXT NOT NULL,
  "issued_at" TEXT NOT NULL,
  "expires_at" TEXT,
  "support" TEXT,
  "recorded_by" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, subject) REFERENCES qualification_subject (tenant, id),
  FOREIGN KEY (tenant, definition) REFERENCES qualification_definition (tenant, id),
  FOREIGN KEY (tenant, level) REFERENCES qualification_level (tenant, id),
  FOREIGN KEY (tenant, issuer) REFERENCES party (tenant, id),
  FOREIGN KEY (tenant, support) REFERENCES evidence_seal (tenant, id)
);

CREATE TABLE qualification_definition (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "key_" TEXT NOT NULL,
  "pin" TEXT NOT NULL,
  "label" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, pin) REFERENCES specification_pin (tenant, id)
);

CREATE TABLE qualification_level (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "definition" TEXT NOT NULL,
  "code" TEXT NOT NULL,
  "rank" INTEGER NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, definition) REFERENCES qualification_definition (tenant, id)
);

CREATE TABLE qualification_requirement (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "definition" TEXT NOT NULL,
  "minimum_level" TEXT,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, definition) REFERENCES qualification_definition (tenant, id),
  FOREIGN KEY (tenant, minimum_level) REFERENCES qualification_level (tenant, id)
);

CREATE TABLE qualification_revocation (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "qualification" TEXT NOT NULL,
  "effective_at" TEXT NOT NULL,
  "reason" TEXT NOT NULL,
  "recorded_by" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, qualification) REFERENCES qualification (tenant, id)
);

CREATE TABLE qualification_subject (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "label" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id)
);

CREATE TABLE artifact_record (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "record" TEXT NOT NULL,
  "revision" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, record) REFERENCES record (tenant, id),
  FOREIGN KEY (tenant, revision) REFERENCES artifact_revision (tenant, id)
);

CREATE TABLE record (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "rule" TEXT NOT NULL,
  "trigger" TEXT NOT NULL,
  "triggered_at" TEXT NOT NULL,
  "retain_until" TEXT NOT NULL,
  "support" TEXT,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, rule) REFERENCES retention_rule (tenant, id),
  FOREIGN KEY (tenant, support) REFERENCES evidence_seal (tenant, id)
);

CREATE TABLE record_category (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "label" TEXT NOT NULL,
  "meaning" TEXT,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, meaning) REFERENCES concept_revision (tenant, id)
);

CREATE TABLE record_event (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "record" TEXT NOT NULL,
  "ordinal" INTEGER NOT NULL,
  "previous" TEXT,
  "kind" TEXT NOT NULL,
  "hold" TEXT,
  "active_holds" INTEGER NOT NULL,
  "effective_at" TEXT NOT NULL,
  "reason" TEXT NOT NULL,
  "authority" TEXT NOT NULL,
  "support" TEXT,
  "recorded_by" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, record) REFERENCES record (tenant, id),
  FOREIGN KEY (tenant, previous) REFERENCES record_event (tenant, id),
  FOREIGN KEY (tenant, hold) REFERENCES record_event (tenant, id),
  FOREIGN KEY (tenant, support) REFERENCES evidence_seal (tenant, id)
);

CREATE TABLE retention_rule (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "category" TEXT NOT NULL,
  "trigger" TEXT NOT NULL,
  "period_days" INTEGER NOT NULL,
  "disposition" TEXT NOT NULL,
  "authority" TEXT NOT NULL,
  "source" TEXT NOT NULL,
  "support" TEXT,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, category) REFERENCES record_category (tenant, id),
  FOREIGN KEY (tenant, support) REFERENCES evidence_seal (tenant, id)
);

CREATE TABLE realization (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "pin" TEXT NOT NULL,
  "build_hash" TEXT NOT NULL,
  "manifest_digest" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, pin) REFERENCES specification_pin (tenant, id)
);

CREATE TABLE repository (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "key_" TEXT NOT NULL,
  "provider" TEXT NOT NULL,
  "locator" TEXT NOT NULL,
  "version" INTEGER NOT NULL,
  PRIMARY KEY (tenant, id)
);

CREATE TABLE specification_pin (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "repository" TEXT NOT NULL,
  "anchor" TEXT NOT NULL,
  "revision" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, repository) REFERENCES repository (tenant, id)
);

